import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 2 Spare that spider","description":"学习 数量词与可数性，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 2 Spare that spider","description":"学习 数量词与可数性，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 数量词与可数性，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 1 Finding fossil man","link":"/life/english/new-concept/book-4/unit-01/lesson-001"},"next":{"text":"第四册：流利英语 · Lesson 3 Matterhorn man","link":"/life/english/new-concept/book-4/unit-01/lesson-003"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 1 Finding fossil man","link":"/life/english/new-concept/book-4/unit-01/lesson-001"},"next":{"text":"第四册：流利英语 · Lesson 3 Matterhorn man","link":"/life/english/new-concept/book-4/unit-01/lesson-003"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-01/lesson-002.md","filePath":"life/english/new-concept/book-4/unit-01/lesson-002.md"}'),i={name:"life/english/new-concept/book-4/unit-01/lesson-002.md"};function s(r,e,l,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-lesson-2-spare-that-spider" tabindex="-1">第四册：流利英语 · Lesson 2 Spare that spider <a class="header-anchor" href="#第四册-流利英语-·-lesson-2-spare-that-spider" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 2 Spare that spider&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕蜘蛛与昆虫数量的关系，练习阅读生态说明中的数量表达和因果论证。注意日常厌恶感并不构成生态价值判断的证据，也不把所有蜘蛛一概描述为无害。输出时要能说明某一观察适用于什么地点或条件，而不是给整个物种下绝对结论。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>spider</td><td>/ˈspaɪdə/</td><td>n.</td><td>蜘蛛</td><td>a garden spider</td></tr><tr><td>insect</td><td>/ˈɪnsekt/</td><td>n.</td><td>昆虫</td><td>insect populations</td></tr><tr><td>prey</td><td>/preɪ/</td><td>n.</td><td>猎物</td><td>catch prey</td></tr><tr><td>balance</td><td>/ˈbæləns/</td><td>n.</td><td>平衡</td><td>ecological balance</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>feed on — 以某物为食</li><li>play a role in — 在某过程中起作用</li></ul><h2 id="语法讲解-数量词与可数性" tabindex="-1">语法讲解：数量词与可数性 <a class="header-anchor" href="#语法讲解-数量词与可数性" aria-label="Permalink to &quot;语法讲解：数量词与可数性&quot;">​</a></h2><p>fewer 修饰可数名词复数，less 通常修饰不可数名词；a number of 后面接复数谓语，the number of 则把数量视为整体，接单数谓语。insects 是可数名词，damage 通常不可数。生态比较还必须交代比较对象和时间范围；fewer insects 只说明数量较少，不自动证明差异由蜘蛛造成。相关观察与因果解释应分开表达。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The number of insects was lower in the sheltered garden.</p></blockquote><p>避风花园中的昆虫数量较少。</p><p>主语中心词是 number，因此用 was；of insects 限定数量的对象，lower 是表语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>The number of insects were lower 错在主谓一致；但 A number of insects were found 中复数正确。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>读示范时区分 insects 的复数尾音与 insect；在 fewer 与 may 上轻度强调，让听者听出数量和推断强度。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>We counted fewer insects near the old wall. Spiders may have contributed to the difference. We also need to compare the plants in both areas.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>为学校花园写三句观察记录，包含昆虫数量、可能解释和一个待控制变量。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>用 fewer 描述观察，用 may 保留解释空间，最后指出植物这一混杂因素。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：A number of spiders ___ found near the wall.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> were</p><p><strong>解析：</strong> a number of 表若干，谓语随 spiders 用复数。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>选择：fewer / less damage。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> less damage</p><p><strong>解析：</strong> damage 表损害时通常不可数。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>“有蜘蛛的地方虫少”单独足以证明因果吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不足。</p><p><strong>解析：</strong> 还可能有温度、植物或农药等其他变量。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：数量词与可数性。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-001">上一课</a> · <a href="/life/english/new-concept/book-4/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-01/lesson-003">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",s]]);export{u as __pageData,b as default};
